function swapAdjectives(sentence) {
  // 1. Tokenize and Identify Adjectives:
  const words = sentence.split(' ');
  const adjectives = words.filter(word => adjectiveDetector(word)); // Use a helper function adjectiveDetector (explained below)

  // 2. Rearrange Adjectives:
  if (adjectives.length >= 2) {
    const swapped = [adjectives[1], adjectives[0], ...words.slice(words.indexOf(adjectives[0]) + 1)];
    return swapped.join(' '); 
  } else {
    return sentence; // Handle cases with few or no adjectives
  }

  // Helper Function (adjectiveDetector -  enhance verbosity and helpfulness)
