function extractEvenNumbers(numbers) {
  // Creates a new array to store the extracted even numbers.
  const evenNumbers = []; 

  // Iterates through each number in the input array 'numbers'.
  for (let number of numbers) {
    // Checks if the number is divisible by 2 (even).
    if (number % 2 === 0) {
      // If even, push it into the 'evenNumbers' array.
      evenNumbers.push(number);
    }
  }
  // Returns the array containing only the extracted even numbers.
  return evenNumbers;
}

