async function postToSlack(text, channelId, accessToken) {
  // **Helpfulness (High):** Clearly outlines the function's purpose and parameters.
  /**
   * Posts a given text message to a specified Slack channel using the provided API token.
   * @param {string} text - The message content to send.
   * @param {string} channelId - The unique ID of the Slack channel.
   * @param {string} accessToken - Your valid Slack API access token with necessary permissions.
   * @returns {Promise<Object>} Resolves with the Slack API response object on success, rejects on error.
   */

  try {
    const slackWebhookUrl = `https://slack.com/api/chat.postMessage`; // Standard Slack API endpoint
    const payload = {
      channel: channelId,
      text: text,
      // Optional: Add more formatting/elements like blocks, attachments for richer messages (Verbosity)
    };

    const response = await fetch(slackWebhookUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${accessToken}`, // Authentication with access token
      },
      body: JSON.stringify(payload),
    });

    // **Helpfulness (High):**  Handles success and error scenarios with clear logging.
    if (!response.ok) {
      throw new Error(`Slack API Error: ${await response.text()}  (Status: ${response.status})`); 
    }
    return await response.json(); // Return API response for debugging/further use
  } catch (error) {
    console.error("Slack Posting Error:", error); // Log detailed errors for debugging
    throw error; // Re-throw to indicate failure
  }
}
