async function sendMessageToSlack(text, channelId) {
  // **1. Weighted Emphasis: Verbose Explanation & Helper Setup** (Verbosity: High)

  /**
   * This function leverages the Slack API to post a given `text` message to a specified Slack channel identified by `channelId`. 
