const slackApi = require('slack-client'); // Assuming you've installed the 'slack-client' library

/**
 * Posts a message to a specified Slack channel using the API.
 *
 * @param {string} text - The content of the message to post.
 * @param {string} channelId - The ID of the Slack channel to target.
 * @param {object} [apiOptions={}] - Optional Slack API configuration (token, etc.). Defaults to using environment variables if set.
 * @returns {Promise<void>} Resolves upon successful message posting, rejects on errors.
 */
async function postToSlack(text, channelId, apiOptions = {}) {
  // 1. API Setup (Prioritize Environment Variables for Security)
  const token = process.env.SLACK_API_TOKEN || apiOptions.token; // Fetch from env or provided options
  if (!token) {
    return Promise.reject(new Error("Missing Slack API token! Set SLACK_API_TOKEN env var or provide in apiOptions."));
  }
  const client = new slackApi(token, true); // Initialize with bot mode (true) for API calls

  // 2. Message Formatting & Posting
  try {
    await client.rtm.sendMessage(text, channelId);
    console.log(`Message "${text}" successfully posted to channel #${channelId}`);
  } catch (error) {
    console.error(`Error posting to Slack:`, error);
    throw error; // Re-throw for proper error handling
  } finally {
    client.disconnect(); // Disconnect after use (good practice)
  }
}

// Example Usage:
postToSlack("Hello from my JavaScript function!", "C123ABC456DEF", { username: "MyBot" })
  .then(() => console.log("Posting complete!"))
  .catch(err => console.error(err));
```

