#include <iostream>
#include <vector>
#include <nlohmann/json.hpp> // Using nlohmann/json for robust JSON handling

using json = nlohmann::json;
using namespace std;

// In-place Bubble Sort with optimized memory usage
void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    do {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                swapped = true; 
            }
        }
        n--; // Reduce search space after each pass
    } while (swapped);
}

