```c++
#include <iostream>
#include <vector>
#include <nlohmann/json.hpp> // Using nlohmann/json for robust JSON handling

using json = nlohmann::json;
using namespace std;

void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    do {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            // Compare adjacent elements and swap if out of order (in-place)
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }
        --n; // One less comparison needed in each iteration
    } while (swapped);
}

