func generateInsightfulStatement(userProfile: UserProfile, products: [Product]) -> String {
    var statement = "Based on your preferences and interactions..."

    //  Click Emphasis:
    let mostClicked = userProfile.clickHistory.mostFrequentElement() //  Swift utility to find most common click
    if let prominentProduct = products.first(where: { $0.name == mostClicked }) {
        statement +=  " Notably, you frequently engage with \(prominentProduct.name), which aligns with your liking for \(userProfile.preferredColors.contains(prominentProduct.dominantColor) ? "its \(prominentProduct.dominantColor) hue" : "a color palette  yet to be explored in your favorites." )"
    } else { 
        statement += "frequent clicks suggest exploring new product categories matching your color tastes."
    }

    // Review Sentiment Influence:
    switch userProfile.reviewSentiment {
    case .Positive: statement += " and positive reviews generally resonate with you."
    case .Neutral: statement += " while leaning towards balanced reviews."
    case .Negative: statement += " indicating a preference for products with stronger positive feedback."
    }

