import Foundation

func generateSportComparison(sportPreference: String) -> [[String: String]] {
    var comparisonData: [[String: String]] = [] 

    //  Define Factors and Weighted Analysis (Adaptable for Excel Columns)
    let factors = [
        "Speed": ["Skiing": "High (especially downhill), efficient cruising", "Snowboarding": "Moderate to High (freeride focus), carving emphasis"],
        "Difficulty": ["Skiing": "Generally gentler initial learning curve, advanced techniques steeper", "Snowboarding": "Steeper initial learning curve, but progressive progression"],
        "Style": ["Skiing": "Classic, elegant, versatile across terrains", "Snowboarding": "More edgy, freestyle-oriented, expressive"],
        "Learning Curve": ["Skiing": "Relatively faster initial grasp, mastering finesse takes time", "Snowboarding": "Initial hurdle, but once adapted, progress can be rapid"],
        "Terrain Variety": ["Skiing": "Excellent adaptability to groomed runs, backcountry, parks", "Snowboarding": "Strong in parks, powder, and freeriding, adapting to groomed less intuitively"],
        "Trick Opportunities": ["Skiing": "Growing aerial tricks, park skiing prominent", "Snowboarding": "Widely renowned for freestyle tricks, grabs, spins, etc."],
    ]

    // User Input Driven Analysis ( Populate with Weighted Insights)
    for (factor, descriptions) in factors {
        let skiingDesc = descriptions["Skiing"] ?? "" // Default to empty if missing
        let snowboardingDesc = descriptions["Snowboarding"] ?? ""
        let userEmphasis = sportPreference == "skiing" ? skiingDesc : snowboardingDesc 
        comparisonData.append([factor: userEmphasis])
    }

    return comparisonData
}

