            _obtainAuthToken = obtainAuthToken; // Inject token retrieval logic here
        }

        protected async Task<HttpResponseMessage> MakeRequestWithAuth(HttpMethod method, string relativeUrl, object data = null, string contentType = "application/json")
        {
            // 1. Obtain Auth Token (Handle Refresh if Needed)
            string accessToken = await _obtainAuthToken?.Invoke("REST Service Call"); // Call delegate for token
            if (string.IsNullOrEmpty(accessToken))
                throw new Exception("Failed to obtain authentication token");

            // 2. Add Authentication Header
            _httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {accessToken}");

            // 3. Build and Send Request
            var content = data != null ? new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, contentType) : null;
            return await _httpClient.SendAsync(new HttpRequestMessage(method, relativeUrl) { Content = content });
        }

        // Generic Methods (Composable & Extensible)
        public async Task<T> GetAsync(string relativeUrl) => await HandleResponse<T>(await MakeRequestWithAuth(HttpMethod.Get, relativeUrl));
        public async Task<T> PostAsync<TData>(string relativeUrl, TData data) => await HandleResponse<T>(await MakeRequestWithAuth(HttpMethod.Post, relativeUrl, data));
        public async Task<T> PutAsync<TData>(string relativeUrl, TData data) => await HandleResponse<T>(await MakeRequestWithAuth(HttpMethod.Put, relativeUrl, data));
