import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import * as dotenv from 'dotenv';
dotenv.config(); // Assuming environment variables for roles & permissions are loaded here

const PERMISSIONS = [
  'READ_USERS',
  'CREATE_USERS',
  'UPDATE_USERS',
  'DELETE_USERS',
  'READ_PRODUCTS',
  'CREATE_PRODUCTS',
  'UPDATE_PRODUCTS',
  'DELETE_PRODUCTS',
  // ... add more permissions as needed
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public endpoint

    const request = context.switchToHttp().getRequest();
    const user = request.user; 
    if (!user || !user.role) throw new UnauthorizedException();

    const userPermissions = await this.prisma.user.findUnique({ where: { id: user.id } }).permissions();
    const hasRequiredRole = requiredRoles.some(role => user.role === role);
    const hasRequiredPermission = PERMISSIONS.some(permission => userPermissions.includes(permission));

    return hasRequiredRole && hasRequiredPermission;
  }
}
