import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { UserService } from './user.service';
import { Role } from './enums/role.enum';
import * as Permissions from './permissions.json'; // Assuming permissions.json holds an array like: ["READ_DATA", "CREATE_USERS", etc.]

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private userService: UserService) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    const request = context.switchToHttp().getRequest();
    const user = request.user; 

    if (!user || !user.role) {
      throw new UnauthorizedException('User not authenticated');
    }

    return requiredRoles ? 
      requiredRoles.some(role => user.role === role && this.hasPermission(user, requiredRoles)) : true;
  }

  hasPermission(user: any, requiredRoles: Role[]): boolean {
    const userPermissions = this.userService.getUserPermissions(user.id); // Fetch dynamic permissions from DB using TypeORM
    return requiredRoles.every(role => Permissions[role] && userPermissions.includes(Permissions[role]));
  }
}

// Example usage in a controller method decorator:
// @UseGuards(RolesGuard({ roles: [Role.ADMIN] }))
// async handleAdminAction(...) { ... }
