function extractNestedValueByDotNotation(options, keyString) {
  // Helper function to recursively traverse nested objects
  const traverseAndExtract = (obj, keys) => {
    if (keys.length === 0) {
      return obj; // Base case: Found matching key, return the value
    }
    const currentKey = keys.shift();
    if (obj && typeof obj === 'object' && currentKey in obj) {
      return traverseAndExtract(obj[currentKey], keys); // Continue traversal
    } else {
      return undefined; // Key not found, propagate undefined upwards
    }
  };

  // Process input: split dot notation into keys
  const keys = keyString.split('.');

  // Perform the recursive extraction
  return traverseAndExtract(options, keys);
}

// Example Usage:
const options = {
  user: {
    profile: { name: "Alice", age: 30 },
    address: { city: "New York" }
  },
  settings: { theme: "dark" }
};

const value = extractNestedValueByDotNotation(options, "user.profile.name");
console.log(value); // Output: "Alice"

const anotherValue = extractNestedValueByDotNotation(options, "nonexistent.key");
console.log(anotherValue); // Output: undefined 
```

