```javascript
function extractNestedValue(options, dotNotationKey) {
  // Split the dot notation into individual keys for traversal
  const keys = dotNotationKey.split('.');
  let currentEntry = options;

  // Traverse the nested structure, returning null if a key is missing
  for (const key of keys) {
    if (typeof currentEntry !== 'object' || !currentEntry.hasOwnProperty(key)) {
      return null; // Key not found at any level
    }
    currentEntry = currentEntry[key]; 
  }

  return currentEntry; // Return the final matched value
}

// Example Usage:
const myOptions = {
  user: {
    profile: { name: 'Alice', age: 30 },
    address: { city: 'New York' }
  },
  settings: { theme: 'dark' }
};

const userName = extractNestedValue(myOptions, 'user.profile.name'); // Returns "Alice"
console.log(userName); // Output: Alice

const userAge = extractNestedValue(myOptions, 'user.profile.age');   // Returns 30
console.log(userAge);  // Output: 30

const nonExistentValue = extractNestedValue(myOptions, 'invalid.path'); // Returns null
console.log(nonExistentValue); // Output: null
```

**Explanation & Weighted Response Enhancement:**

