function extractNestedValueByDotNotation(options, keyString) {
  // Split the dot-notated key into individual keys
  const keys = keyString.split('.');
  let currentLevel = options;

  // Traverse the nested structure, extracting values at each step
  for (const key of keys) {
    if (typeof currentLevel === 'object' && currentLevel !== null && key in currentLevel) {
      currentLevel = currentLevel[key];
    } else {
      // Key not found, return undefined to signal failure
      return undefined; 
    }
  }

  // Return the final extracted value (found matching nested key)
  return currentLevel;
}
```

