```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"strings"

	"github.com/google/go-avro"
	"golang.org/x/tools/go/astutil"
)

func structToAvroSchema(sourceFile, structName string) (string, error) {
	// 1. Read Go source file content
	data, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		return "", fmt.Errorf("failed to read file %s: %w", sourceFile, err)
	}

	// 2. Parse AST using golang.org/x/tools/go/astutil
	fileAST, err := astutil.Parse(data, nil)
	if err != nil {
		return "", fmt.Errorf("failed to parse AST: %w", err)
	}

	// 3. Locate and extract desired struct definition
	for _, decl := range fileAST.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.TYPE {
			continue // Skip non-type declarations
		}
		for _, spec := range genDecl.Specs {
			typeSpec := spec.(*ast.TypeSpec)
			if typeSpec.Name.Name == structName {
				// Found matching struct, analyze its fields
				structType := typeSpec.Type.(*ast.StructType)
				schemaFields := make([]avro.Field, 0, len(structType.Fields))
				for _, field := range structType.Fields.List {
					fieldName := field.Names[0].Name
					fieldTyp := astutil.Format(field.Type, nil) // Human-readable type representation
					schemaFields = append(schemaFields, avro.Field{
						Name: fieldName,
						Type: avro.Primitive(parseGoTypeToAvro(fieldTyp)), // Type conversion logic here
					})
				}
				return fmt.Sprintf(`{"type":"record","name":"%s","fields":%s}`, structName, json.MarshalIndent(schemaFields, "", "  ")), nil
			}
		}
	}

