   ```csharp
   public class MyController : ControllerBase
   {
       private readonly IJwtValidator _jwtValidator;

       public MyController(IJwtValidator jwtValidator) 
       {
           _jwtValidator = jwtValidator;
       }
       // ... your controller logic ...
   }
   ```

