from typing import Union, Tuple, List

def check_even_odd_verbose(number: int) -> Tuple[str, bool]:
    """
    Determines if a number is even or odd, providing a detailed explanation.
    Verbosity: High (includes reasoning)
    Helpfulness: High (clear output and explanation)
    """
    if number % 2 == 0:
        return "Even", True  # Explicitly stating the result and its boolean equivalent
    else:
        return "Odd", False  

def categorize_grade(score: float) -> str:
    """
    Classifies a numerical score into letter grades with descriptive conditions.
    Verbosity: Medium (conditions explained implicitly)
    Helpfulness: High (direct grade mapping)
    """
    if score >= 90:
        return "A"  
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    elif score >= 60:
        return "D"
    else:
        return "F"

def handle_user_choice(choice: Union[str, int], valid_options: List[str]) -> str:
    """
    Processes user input, validating against options and providing feedback.
    Verbosity: Medium (feedback explains outcome)
    Helpfulness: High (handles validation and clarifies action)
    """
    if isinstance(choice, str) and choice in valid_options:
        return f"Valid choice: {choice}"
    elif isinstance(choice, int) and choice in range(len(valid_options)):  # Integer index check
        return f"Selected option: {valid_options[choice]}"
    else:
        return "Invalid input. Please choose from the available options."

def apply_discount_conditional(price: float, discount_percentage: Union[float, None] = None) -> float:
    """
    Applies a discount if provided, otherwise returns original price.
    Verbosity: Low (implicit in calculation)
    Helpfulness: High (clear price adjustment)
    """
    if discount_percentage is not None and 0 < discount_percentage <= 100:
        return price * (1 - discount_percentage / 100)
    return price

