```php
<?php

// Assuming your transaction data is stored in a MySQL database table named 'transactions' with columns:
//  - customer_id (INT)
//  - product_id (INT) -  ID of the specific coffee product (e.g., 'latte')
//  - purchase_date (DATE)

// 1. Establish Database Connection
$conn = new mysqli("localhost", "username", "password", "database_name");
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// 2. Define Target Product ID
$targetProductId = 123; // Replace with the actual ID of the desired coffee product

// 3. Construct SQL Query with GROUP BY and HAVING
$sql = "
    SELECT customer_id 
    FROM transactions
    WHERE product_id = $targetProductId
    GROUP BY customer_id
    HAVING COUNT(DISTINCT purchase_date) >= 3 
    AND DATE_SUB(MAX(purchase_date), INTERVAL 7 DAY) >= CURDATE()  -- Purchases within the last week
";

// 4. Execute Query and Fetch Results
$result = $conn->query($sql);

// 5. Process and Present Loyal Customers
if ($result->num_rows > 0) {
    echo "<h2>Loyal Customers for '$targetProduct' (past week):</h2>";
    echo "<ul>";
    while($row = $result->fetch_assoc()) {
        $customerId = $row["customer_id"];
        echo "<li>Customer ID: $customerId</li>"; 
    }
    echo "</ul>";
} else {
    echo "No customers met the criteria for loyalty this week.";
}

// 6. Close Connection
$conn->close();

?>
```

