import { Injectable, MiddlewareFunction, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvConditionalMiddlewareDecorator {
  static create(condition: boolean): MethodDecorator {
    return (target: Object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
      const originalMethod = descriptor.value;

      descriptor.value = async function (...args: any[]) {
        const context = (this as any).getContext<ExecutionContext>(); // Assuming your middleware has access to ExecutionContext
        const envValue = process.env.NODE_ENV === 'true' ? true : false; // Safely interpret NODE_ENV

        if (envValue === condition) {
          // Proceed only if NODE_ENV matches the condition
          return await originalMethod.apply(this, args) || true; // Ensure 'next()' like behavior by returning true
        } else {
          // Skip execution based on condition
          return false; 
        }
      };

      return descriptor;
    };
  }
}

// Usage Example:

// Create a middleware that only runs in development (NODE_ENV='true')
@Middleware(EnvConditionalMiddlewareDecorator.create(true))
export class DevModeMiddleware implements MiddlewareFunction {
  async execute(context: ExecutionContext) {
    // Your dev-specific logic here...
    console.log('Executing in development mode');
    return true; // Indicate successful continuation
  }
}
