import { MiddlewareFn, Injectable } from '@nestjs/common';
import { ExecutionContext } from '@nestjs/core';

@Injectable()
export const EnvConditionalMiddleware = (envVariable: string, condition: boolean) => {
  return (next: MiddlewareFn<any>) => {
    const envValue = process.env[envVariable];
    // Weighted reasoning: Prioritize clarity and explicitness (high verbosity) for understanding the logic
    if (envValue && envValue.toLowerCase() === (condition ? 'true' : 'false')) {
      return next(); // Call next middleware/route handler if condition matches
    } else {
      console.log(`Environment variable '${envVariable}' does not meet the condition (${condition ? 'true' : 'false'}), skipping execution.`);
      return false; // Short-circuit, prevent further processing
    }
  };
};

// Usage Example (specifically for NODE_ENV):
export const ConditionalByNodeEnv = (allowInProduction: boolean) => 
  EnvConditionalMiddleware('NODE_ENV', allowInProduction);

// Apply the decorator to a middleware or route handler
@Middleware(ConditionalByNodeEnv(true)) // Only execute in production (NODE_ENV='production')
export class MyProductionMiddleware {
  // ... your middleware logic ...
}
