```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';

// Decorator function to apply the conditional middleware logic
export const ConditionalEnvMiddleware = (envValue: string) =>
  (target: Object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async (req, res, next) => {
      if (process.env[envValue] === 'true') {
        // Proceed only if NODE_ENV (or your specified env variable) is 'true'
        await originalMethod.apply(this, [req, res, next]); 
      } else {
        // Otherwise, short-circuit and prevent further execution
        return false; 
      }
    };
    return descriptor;
  };

// Example Usage (assuming you want to check 'NODE_ENV'):
@Injectable()
export class MyConditionalMiddleware implements NestMiddleware {
  @ConditionalEnvMiddleware('NODE_ENV') // Apply decorator with 'NODE_ENV'
  async execute(req: Request, res: Response, next: NextFunction) {
    // Your middleware logic (executed only in 'true' NODE_ENV)
    console.log('Middleware running in production environment');
    next(); 
  }
}
```

