public class HaikuGenerator
{
    private static readonly Dictionary<string, List<string>> ThematicWords = new Dictionary<string, List<string>>
    {
        { "solitude", new List<string> {"standing, lone," , "silent vigil," , "whispers unheard"}},
        { "misty_meadow", new List<string> {"soft veil descends," , "emerald hues blur," , "dawn's breath ethereal"}},
        { "tall_tree", new List<string> {"ancient boughs reach," , "rooted firm, unyielding," , "skyward sentinel"}}
    };

    public static string GenerateHaiku(string themeEmphasis = "solitude")
    {
        Random rand = new Random();
        List<string> lines = new List<string>();
        lines.Add(ThematicWords[themeEmphasis][rand.Next(ThematicWords[themeEmphasis].Count)]); // Line 1 (Emphasis)
        lines.Add(ThematicWords["misty_meadow"][rand.Next(ThematicWords["misty_meadow"].Count)]); // Line 2 (Setting)
        lines.Add(ThematicWords["tall_tree"][rand.Next(ThematicWords["tall_tree"].Count)]); // Line 3 (Central Element)
        return string.Join("\n", lines);
    }
}

// Usage Example:
