**1.  Unified Permissions & Stream Management (Recommended for Modern Approaches)**

   ```javascript
   async function manageMediaAccess(cameraOn, micOn, successCallback, errorCallback) {
       const constraints = {
           video: cameraOn ? { deviceId: { exact: await getPreferredCameraId() } } : false,  // Explicit device selection if desired
           audio: micOn ? true : false 
       };

       try {
           const stream = await navigator.mediaDevices.getUserMedia(constraints);
           successCallback(stream); // Pass the active stream for utilization (e.g., in RTCPeerConnection, video elements)
       } catch (err) {
           errorCallback(err); // Handle permission denials or errors gracefully
       }
   }

   // Usage Example:
   async function startMedia() {
       manageMediaAccess(true, true, (stream) => {
           document.getElementById('videoElement').srcObject = stream; // Display camera feed
           // ... handle audio input similarly using stream
       }, (err) => console.error('Media Access Error:', err));
   }

   async function stopMedia() {
       const stream = document.getElementById('videoElement').srcObject; // Retrieve active stream
       stream.getTracks().forEach(track => track.stop()); // Safely stop tracks
       // ... handle microphone track stopping as well
   }
