               audio: micOn ? true : false  // Enable/disable audio capture
           };

           const stream = await navigator.mediaDevices.getUserMedia(constraints);

           //  Handle Stream (Display/Usage):
           if (cameraOn) {
               document.getElementById('videoElement').srcObject = stream; // Assuming you have a `<video>` element
           }
           if (micOn) {
               //  Integrate stream with audio context for recording, playback, etc.
           }

           //  Cleanup (Essential for resource management)
           return () => stream.getTracks().forEach(track => track.stop()); 
       } catch (err) {
           console.error("Permission denied or device issue:", err);
       }
   }

   // Usage Examples:
   manageMedia(true, true);  // Open both camera and microphone
   manageMedia(false, true); // Only microphone active
   ```

