        setEmails(results);
      } else {
        setEmails([]); // Clear suggestions on short prefixes
      }
    };

    const timer = setTimeout(() => debouncedSearch(inputValue), 300); // Debounce delay (ms)
    return () => clearTimeout(timer);
  }, [inputValue]);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
  };

  const handleSelectedItem = (email: string) => {
    setSelectedItem(email);
    setInputValue(email); // Set input to selected item
  };

  return (
    <StyledComboboxContainer>
      <Combobox
        value={selectedItem || inputValue}
        onChange={handleInputChange}
        onInputKeyDown={(event) => {
          // Handle Enter/Tab key presses for selection
