using Accord.MachineLearning;
using Accord.MachineLearning.Bayes;
using Accord.NLP;
using System;
using System.Collections.Generic;
using System.Linq;

public class NaiveBayesTextClassifier
{
    public static void Main(string[] args)
    {
        // 1. **Prepare Labeled Dataset (Simulated for brevity)**
        var dataset = new List<Tuple<string, string>>
        {
            ("The debate sparked heated political discourse.", "Politics"),
            ("Ronaldo scored a stunning goal, thrilling fans.", "Sports"),
            ("New movie release garnered critical acclaim.", "Entertainment"),
            // ... populate with your actual labeled sports, politics, entertainment sentences ...
        };

        // 2. **Feature Extraction with CountVectorizer**
        var vectorizer = new CountVectorizer();
        var vocabulary = vectorizer.BuildVocabulary(dataset.Select(x => x.Item1));
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Item1));

        // 3. **Naive Bayes Model Training**
        var naiveBayes = new NaiveBayes<string>(featureMatrix, dataset.Select(x => x.Item2).ToArray());
        naiveBayes.Train();

        // 4. **Conditional Probability Insight (Demonstrative - Extract for specific case if needed)**
        //  *You'd typically access these probabilities through internal model structures for direct analysis*
        Console.WriteLine("Example Conditional Probability (Illustrative - adapt for full extraction):");
        foreach (var category in naiveBayes.Classes)
        {
            var wordProb = naiveBayes.GetClassProbabilities(vocabulary["game"], category); // Probability of "game" given category
            Console.WriteLine($"P(game | {category}) : {wordProb}"); 
        }

        // 5. **Classification of New Sentence**
        string newSentence = "The sports game was exciting.";
        var transformedSentence = vectorizer.Transform(newSentence);
        string prediction = naiveBayes.Decide(transformedSentence);
        Console.WriteLine($"\nPrediction for '{newSentence}': {prediction}"); 
    }
}
```

