import { useEffect, useRef, useState } from 'react';

const useRemoveWidowChars = () => {
  const textRef = useRef(null);
  const [processedText, setProcessedText] = useState('');

  useEffect(() => {
    if (textRef.current) {
      const removeWidowHandler = () => {
        const text = textRef.current.value;
        // Logic to identify and remove widow characters (typically spaces at the end of lines followed by non-breaking spaces)
        const processed = text.replace(/(?<=\s)\u00A0(?=\s|$)/g, ' '); // Regex for NBSP removal
        setProcessedText(processed);
      };

      // Attach event listener for updates (e.g., input changes)
      const inputElement = textRef.current;
      inputElement.addEventListener('input', removeWidowHandler);
      // Cleanup on unmount to prevent memory leaks
      return () => inputElement.removeEventListener('input', removeWidowHandler);
    }
  }, [textRef]); // Dependency array ensures re-processing on textRef changes

  return { processedText, setText: setProcessedText, ref: textRef };
};

// Usage Example:
const MyComponent = () => {
  const { processedText, setText, ref } = useRemoveWidowChars();

  return (
    <textarea ref={ref} value={processedText} onChange={(e) => setText(e.target.value)} />
  );
};
