import React, { useEffect, useRef } from 'react';

const RemoveWidowCleaner = ({ children }) => {
  const textContainerRef = useRef(null);

  useEffect(() => {
    // Function to handle widow removal (CSS solution for brevity)
    const removeWidows = () => {
      if (textContainerRef.current) {
        const style = document.createElement('style');
        style.innerHTML = `
          ${textContainerRef.current.querySelectorAll('p:last-child').length > 0 ? '' : 'p:last-child::after { content: " "; display: inline-block; width: 0; }'}
        `;
        document.head.appendChild(style);
      }
    };

    removeWidows(); // Initial cleanup
    // Cleanup on component update (reapply widow fix if needed)
    return () => document.head.removeChild(document.querySelector('style[data-widow-cleaner]')); 
  }, []); // Empty dependency array ensures effect runs only once on mount

  return <div ref={textContainerRef}>{children}</div>;
};

export default RemoveWidowCleaner;
```

