        // Debounce to avoid excessive recalculations (e.g., using lodash's debounce or a simple timeout)
        setTimeout(removeWidows, 300); 
      });

      return () => window.removeEventListener('resize', removeWidows); // Cleanup on unmount
    }
  }, []); // Empty dependency array ensures effect runs only once on mount

  return textContainerRef;
};

