// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor(options = {}) {
    this.client = redis.createClient({
      ...options, // Allow customization via options (host, port, password, etc.)
    });

    // Robust error handling with console logging
    this.client.on('error', (err) => console.error('Redis Client Error:', err)); 
  }

  isAlive() {
    return new Promise((resolve) => {
      this.client.ping((err, reply) => {
        if (err) {
          resolve(false); // Connection issue
        } else {
          resolve(true); // Successful ping
        }
      });
    });
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error(`Error retrieving from Redis (key: ${key}):`, err);
      throw err; // Re-throw for higher-level handling
    }
  }

  async set(key, value, durationInSeconds) {
    try {
      await this.client.SET(key, value, 'EX', durationInSeconds);
      console.log(`Stored value '${value}' for key '${key}' expiring in ${durationInSeconds} seconds`);
    } catch (err) {
      console.error(`Error setting in Redis (key: ${key}):`, err);
      throw err;
    }
  }

  async del(key) {
    try {
      const deleted = await this.client.DEL(key);
      console.log(`Deleted key '${key}' (deleted: ${deleted})`);
      return deleted; // Return confirmation count
    } catch (err) {
      console.error(`Error deleting from Redis (key: ${key}):`, err);
      throw err;
    }
  }
}

// Create and export an instance
const redisClient = new RedisClient(); 
module.exports = redisClient;
```

