package main

import "fmt"

func detectDoubleNegative(sentence string) {
	// 1. Define a slice of explicit negative words (enhancement for accuracy)
	negativeWords := []string{"not", "never", "rarely", "scarcely", "hardly", "no", "none"}

	// 2. Iterate through each negative word in the predefined list
	for _, word := range negativeWords {
		// 3. Check for pattern: "not" followed by the negative word within the sentence
		if strings.Contains(sentence, "not "+word) {
			// 4.  Conditional Double Negative Identification
			fmt.Printf("Sentence '%s' contains a double negative using '%s'.\n", sentence, word)
			return // Exit early after finding one instance
		}
	}
	// 5. No double negative pattern found
	fmt.Println("Sentence does not contain a clear double negative.")
}

func main() {
	testSentence1 := "He isn't not worried about the coronavirus situation"
	testSentence2 := "She rarely visits, almost never."
	detectDoubleNegative(testSentence1)
	detectDoubleNegative(testSentence2)
}
