```go
package main

import (
	"fmt"
	"strings"
)

func detectDoubleNegative(sentence string) {
	// 1. Define a slice of common negative words to watch for in double negatives
	negativeWords := []string{"not", "never", "rarely", "seldom", "no", "none", "nothing"}

	// 2. Tokenize the sentence into words for easier analysis
	words := strings.Split(sentence, " ")

	// 3. Iterate through each word and its preceding context
	for i := range words {
		currentWord := words[i]
		//  Check if the current word IS a negative word from our list
		if contains(negativeWords, currentWord) {
			// 4.  Further examine the *preceding* word for "not" + negative word pattern
			if i > 0 && words[i-1] == "not" && contains(negativeWords, currentWord) {
				fmt.Printf("Double negative detected in sentence: '%s'  (pattern: %s %s)\n", sentence, words[i-1], currentWord)
				return // Exit after finding one instance
			}
		}
	}
	fmt.Println("No double negative found in the sentence.")
}

// Helper function to efficiently check for element presence in a slice
func contains(slice []string, item string) bool {
	for _, v := range slice {
		if v == item {
			return true
		}
	}
	return false
}

func main() {
	sentences := []string{
		"He isn't not worried about the coronavirus situation",
