package main

import (
	"fmt"
	"strings"
)

func detectDoubleNegative(sentence string) {
	// 1. Define a slice of common negative words to watch for in double negatives
	negativeWords := []string{"not", "never", "rarely", "seldom", "no", "none", "without"}

	// 2. Tokenize the sentence into words for analysis
	words := strings.Split(sentence, " ")

	// 3. Iterate through each word and its preceding context
	for i, word := range words {
		//  Check if the current word IS a negative word AND
		//  if the previous word is "not" AND it's not at the very beginning
		if contains(negativeWords, word) && i > 0 && words[i-1] == "not" {
			fmt.Printf("Double negative detected in sentence: %s\n", sentence)
			return // Exit after finding one instance
		}
	}
	// No double negative found within the sentence structure
	fmt.Println("No double negative found in the sentence.")
}

// Helper function to efficiently check for element presence in a slice
func contains(slice []string, item string) bool {
	for _, v := range slice {
		if v == item {
			return true
		}
	}
	return false
}

func main() {
	sentences := []string{
		"He isn't not worried about the coronavirus situation",
		"She rarely visits, nevermind attending events",
		"They have no objections whatsoever",
		"The project progressed smoothly without any setbacks",
		"I am happy about the outcome.",
	}

	for _, sentence := range sentences {
		detectDoubleNegative(sentence)
	}
}
