# Function to check if a SID is exclusively found in a user/group's SIDHistory
function Check-ExclusiveSID {
    param(
        [string]$SID,
        [string]$DomainUserOrGroup
    )

    # Get the SIDHistory for the specified user/group
    $SIDHistory = Get-ADObject -Identity $DomainUserOrGroup -Properties SIDHistory | Select-Object -ExpandProperty SIDHistory

    # Check if the SID exists ONLY in the SIDHistory and not elsewhere in the system
    if ($SIDHistory -contains $SID -and (Get-Acl -Path (Get-Item -Path "$env:systemdrive\temp\$($DomainUserOrGroup)_ACL_Check").PSPath -notcontains $SID)) {
        return $true
    } else {
        return $false
    }
}

# Function to recursively analyze folder ACLs and report findings
function Analyze-RecursiveACLs {
    param(
        [string]$FolderPath,
        [string]$DomainController = "DC01.domain.com" # Replace with your primary DC
    )

    # Get all folders within the specified path recursively
    Get-ChildItem -Path $FolderPath -Recurse | ForEach-Object {
        # Process each folder
        $Folder = $_.FullName

        # Obtain ACL information for the folder
        $Acl = Get-Acl -Path $Folder

        # Iterate through Access Control Entries (ACEs)
        $Acl.Access -ForEach-Object {
            # Extract Subject (User/Group) and SID from each ACE
            $Subject = $_.IdentityReference
            $SID = $_.IdentityReference.Translate($DomainController).Value

            # Check if the SID is exclusive to a user/group's SIDHistory within the domain
            if (Check-ExclusiveSID -SID $SID -DomainUserOrGroup $Subject) {
                Write-Output "WARNING: Folder '$Folder' contains an ACE with SID '$SID' exclusively found in SIDHistory of '$Subject'. This might indicate a potential security concern due to historical association and warrants further review."
            }
        }
    }
}

# Example Usage: Start analysis from 'C:\SensitiveData' directory
Analyze-RecursiveACLs -FolderPath "C:\SensitiveData" 
```

