# Function to check if a SID exists only within a specific user/group's SIDHistory
function Check-SIDInSIDHistory {
    param(
        [string]$SID,
        [string]$PrincipalName # User or Group distinguished name (e.g., "CN=JohnDoe,OU=Users,DC=example,DC=com")
    )

    # Get the Principal's SIDHistory
    $SIDHistory = Get-ADPrincipal -Identity $PrincipalName -Properties SidHistory | Select-Object -ExpandProperty SidHistory

    # Check if the SID is present ONLY in the SIDHistory and not elsewhere in the system
    if ($SIDHistory -contains $SID -and (!(Get-Acl -Path "DistinguishedName:$PrincipalName" -ErrorAction SilentlyContinue | ForEach-Object {$_.Access -like "*S-1-$SID*" }))) {
        return $true
    } else {
        return $false
    }
}

# Recursive function to traverse folders and analyze ACLs
function Analyze-FolderACLs {
    param(
        [string]$FolderPath,
        [string]$DomainController = (Get-ADDomainController).Name # Default to local DC
    )

    # Get all files and folders within the path recursively
    Get-ChildItem -Path $FolderPath -Recurse -File -Directory | ForEach-Object {
        # Analyze ACLs for each item
        $Acl = Get-Acl $_.FullName
        foreach ($AccessRule in $Acl.Access) {
            if ($AccessRule.IdentityReference -is [System.Security.Principal.SecurityIdentifier]) {
                $SID = $AccessRule.IdentityReference.Value

                # Query domain for Principals with matching SID ONLY in their SIDHistory
                Get-ADUser -Filter "objectClass -eq 'user'" -SearchBase "DC=example,DC=com" -Properties DistinguishedName,SidHistory | ForEach-Object {
                    if (Check-SIDInSIDHistory -SID $SID -PrincipalName $_.DistinguishedName) {
                        Write-Output "WARNING: Folder '$_' has ACL referencing SID '$SID' found ONLY in SIDHistory of user/group $($_.DistinguishedName)"
