# Function to recursively check folder ACLs and SIDHistory
function Check-RestrictedSIDs {
    param(
        [string]$Path,
        [switch]$Verbose = $false
    )

    # Get domain users and groups with SIDHistory
    $DomainUsers = Get-ADUser -Filter * -Properties SamAccountName,SidHistory | Select-Object SamAccountName,SidHistory
    $DomainGroups = Get-ADGroup -Filter * -Properties Name,SidHistory | Select-Object Name,SidHistory

    # Combine SIDHistory into a single hashtable for efficient lookup
    $AllSIDs = @{}
    $DomainUsers | ForEach-Object { $AllSIDs += @{ Name = $_.SamAccountName; SIDs = $_.SidHistory } }
    $DomainGroups | ForEach-Object { $AllSIDs += @{ Name = $_.Name; SIDs = $_.SidHistory } }

    # Recursive function to process folders
    function Process-Folder {
        param(
            [string]$Folder,
            [hashtable]$SeenSIDs = @{}
        )
        Get-Acl -Path $Folder | ForEach-Object {
            # Extract SIDs from Access Control Entries (ACEs)
            $_.Access | Where-Object {$_.IdentityReference -ne $null} | ForEach-Object {
                $SID = $_.IdentityReference.Translate([System.Security.Principal.NTAccount])
                if (-not $SeenSIDs.ContainsKey($SID)) {
                    # Check if SID exists only in Domain Users/Groups SIDHistory
                    if (-not $AllSIDs.Keys -contains $SID.Value) {
                        Write-Output -Verbose "WARNING: Restricted SID '$SID' found in ACL of '$Folder' but not in any known Domain User/Group SIDHistory"
                        $SeenSIDs += @{ SID = $SID; Source = $Folder } # Track encountered restricted SIDs
                    }
                }
            }
        }
        # Recursively process subfolders
        Get-ChildItem -Path $Folder -Recurse | Where-Object {$_.PSIsContainer} | ForEach-Object { Process-Folder -Folder $_.FullName -SeenSIDs $SeenSIDs }
    }

    # Initiate the recursive processing
    Process-Folder -Path $Path -Verbose $Verbose
